    s2Body: "Kho tác vụ AI của UVEL liên tục nâng cấp: tác vụ mới hơn cần nhiều sức mạnh tính toán (VRAM) hơn, nên tác vụ bậc cao tăng lên còn lượng tác vụ bậc thấp co lại. Số tác vụ một thiết bị nhận được thu hẹp dần theo từng tháng trong năm đầu — về sau càng nhanh — cho tới khi chỉ còn phần thu nhập ở mức sàn công suất. Thiết bị vừa kích hoạt được trợ cấp ưu tiên tác vụ để luôn chạy đủ công suất. Mức trừ giá khi đổi máy được tính theo bậc mà tổng sản lượng trọn đời của thiết bị rơi vào — càng sản xuất nhiều thì mức trừ giá càng nhỏ.",
    s3Title: "Rủi ro thị trường của token (NEX)",
