    k2Label: "Thưởng Ghép Cân Bằng",
    k2Body:
      "Trả {freq} dựa trên nhánh nhỏ hơn trong hai nhánh × 10%. Cần cả hai nhánh ≥ $1,000/tháng. Xem chi tiết tại Đội nhóm → Ghép Cân Bằng.",
    k3Label: "Đồng cấp · thưởng cùng cấp",
    k3Body:
      "Mở khóa ở V3. Khi các đồng đội cùng cấp hoặc cao hơn bạn mua hàng hợp lệ, bạn nhận 5% — phần thưởng cho những lãnh đạo biết bồi dưỡng ra lãnh đạo khác.",
    k4Label: "Bồi dưỡng · thưởng người bảo trợ (NEX)",
    k4Body:
      "Khi một người bạn mời trực tiếp đạt cấp V mới, bạn nhận một khoản thưởng NEX một lần. Số NEX tăng theo cấp của họ: V1 = 500 NEX, V8 = 10M NEX.",
    k5Label: "Lãnh đạo · phần quỹ tuần",
    k5Body:
      "Mở khóa ở V3. Nền tảng góp 5% tổng doanh số mỗi tuần vào một quỹ, chia cho người dùng V3+ theo trọng số phiếu. Kết toán mỗi thứ Hai.",
    k6Label: "Genesis · phát hành cho nhà sáng lập",
    k6Body:
      "Nếu bạn nắm giữ suất Genesis (NFT suất sáng thế, xem trang Genesis của bạn), bạn nhận một phần doanh thu nền tảng đều đặn, tính theo số suất bạn giữ.",
    s3Title: "Vòng đời kết toán",
