    statusWithdrawn: "ĐÃ RÚT",
    statusWithdrawnDesc:
      "Bạn đã chuyển nó về ví. Được ghi lại phục vụ thuế và báo cáo.",
    s3HintTitle: "Vì sao có thời gian chờ?",
    s3HintBody:
      "Nếu đơn gốc bị hoàn hoặc tranh chấp trong vòng 30 ngày, khoản hoa hồng sẽ tự động bị thu hồi. Qua cửa sổ đó, nó thuộc về bạn vĩnh viễn.",
    s4Title: "Hoa hồng một ngày điển hình",
    s4Intro: "Đây là một ngày có thể trông thế nào với người dùng V3 có đội nhóm đang hoạt động:",
    s4Day: "Hôm nay",
    ex1Label: "Sarah K. mua UVELBox S1 — Hoa hồng trực tiếp",
