    s4Note:
      "Bốn sự kiện này cộng lại đẩy thu nhập ngày của bạn lên. Khi mạng lưới lớn lên và cấp V tăng, càng nhiều luồng mở khóa và càng nhiều sự kiện dồn lại mỗi ngày.",
    faqTitle: "Câu hỏi thường gặp",
